Problem:
A smoothie company offers delivery and ships in specialty delivery and medium bags. A specialty delivery bag can hold 12 orders while a medium bag can hold 7 orders. Most delivery drivers prefer medium bags, so at least three times as many medium bags must be used as specialty delivery bags. The smoothie company has at most 45 medium bags and 60 specialty delivery bags. If the company must send at least 6 specialty delivery bags and can send at most 50 bags in total, how many of each should they send to maximize the total number of smoothies that can be delivered?

Model and facts:
{
 "model": {
  "variables": [
   {
    "name": "specialty delivery bags",
    "lower": 6.0,
    "upper": 60.0,
    "integer": true
   },
   {
    "name": "medium bags",
    "lower": 0.0,
    "upper": 45.0,
    "integer": true
   }
  ],
  "objective": {
   "sense": "max",
   "terms": [
    {
     "var": "specialty delivery bags",
     "coef": 12.0
    },
    {
     "var": "medium bags",
     "coef": 7.0
    }
   ]
  },
  "constraints": [
   {
    "name": "medium bags at least 3 times specialty bags",
    "terms": [
     {
      "var": "medium bags",
      "coef": 1.0
     },
     {
      "var": "specialty delivery bags",
      "coef": -3.0
     }
    ],
    "sense": ">=",
    "rhs": 0.0
   },
   {
    "name": "total bags at most 50",
    "terms": [
     {
      "var": "specialty delivery bags",
      "coef": 1.0
     },
     {
      "var": "medium bags",
      "coef": 1.0
     }
    ],
    "sense": "<=",
    "rhs": 50.0
   }
  ]
 },
 "facts": {
  "objective": 410.0,
  "values": {
   "specialty delivery bags": 12.0,
   "medium bags": 38.0
  },
  "binding": [
   "total bags at most 50"
  ],
  "slack": {
   "medium bags at least 3 times specialty bags": 2.0,
   "total bags at most 50": 0.0
  },
  "shadow_prices": null
 }
}
